import React, { useState, useEffect } from "react";
import { Link as NavLink, useLocation, useLoaderData } from "@tanstack/react-router";

//Styles
import "./Navbar.css";

const Navbar = () => {
  //Variables
  const [isNavExpanded, setIsNavExpanded] = useState(false);
  const [, setActiveMenu] = useState("abc");
  const [isScrolled, setIsScrolled] = useState();
  const loaderData = useLoaderData({ from: '__root__' });
  const [category, setCategory] = useState(loaderData?.categories || []);

  useEffect(() => {
    if (loaderData?.categories) {
      setCategory(loaderData.categories);
    }
  }, [loaderData]);

  //Navbar links
  const navlinks = [
    ["Home", "/"],
    ["Our Products", "/"],
    ["About Us", "/"],
    ["Blog", "/"],
    ["Contact", "/"],
    ["Careers", "/"],
  ];

  const location = useLocation();

  // handle scroll/mouse and google translate initialization
  useEffect(() => {
    const handleScrollOrMove = () => {
      if (location.pathname === "/") {
        setIsScrolled(window.scrollY > 20);
      } else {
        setIsScrolled(true);
      }
    };

    handleScrollOrMove();
    window.addEventListener("scroll", handleScrollOrMove);
    window.addEventListener("mousemove", handleScrollOrMove);

    // Google translate init (run once)
    const googleTranslateElementInit = () => {
      try {
        new window.google.translate.TranslateElement(
          { pageLanguage: "en", autoDisplay: true },
          "google_translate_element",
        );
      } catch (e) {}
    };

    if (!document.getElementById("google-translate-script") && (typeof navigator === 'undefined' || !navigator.userAgent.includes('ReactSnap'))) {
      window.googleTranslateElementInit = googleTranslateElementInit;
      const addScript = document.createElement("script");
      addScript.id = "google-translate-script";
      addScript.setAttribute(
        "src",
        "//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit",
      );
      document.body.appendChild(addScript);
    }
    const intervalId = setInterval(() => {
      try {
        const el = document.getElementById(":1.container");
        if (el) el.style.transform = "scale(0)";
        const parent = el?.parentElement;
        if (parent) parent.style.transform = "scale(0)";
        document.getElementsByTagName("body")[0].style.top = "0px";
        const gEl = document.getElementById("google_translate_element");
        if (gEl) gEl.style.transform = "scale(0)";
      } catch (e) {}
    }, 500);

    return () => {
      window.removeEventListener("scroll", handleScrollOrMove);
      window.removeEventListener("mousemove", handleScrollOrMove);
      clearInterval(intervalId);
    };
  }, [location.pathname]);

  // set active menu based on route
  useEffect(() => {
    const path = location.pathname;
    let menu = "Home";
    if (path === "/") menu = "Home";
    else if (
      path === "/blog" ||
      path.includes("/blog") ||
      path.split("/")[1] === ""
    )
      menu = "Blog";
    else if (path === "/about") menu = "About Us";
    else if (path === "/contact") menu = "Contact";
    else if (
      path === "/careers" ||
      path.includes("/career-details/") ||
      path.includes("/job-apply")
    )
      menu = "Careers";
    else if (path === "/page-not-found") menu = "PageNotFound";
    else if (
      path === "/our-products" ||
      path.includes("/product") ||
      path.split("/")[1] !== ""
    )
      menu = "Our Products";
    else menu = "Home";
    setActiveMenu(menu);
  }, [location.pathname]);

  return (
    // Navbar container
    <div
      className={
        "flex items-center justify-between py-3 px-2  md:px-8 fixed top-0 w-full z-50 transition-all duration-300 " +
        (isScrolled ? " bg-white " : " bg-transparent ") +
        (isScrolled ? " shadow-lg " : " ")
      }
      id="navbarContainer"
    >
      {/* Logo */}
      <div className="absolute top-0 left-0 scale-0 -translate-y-[400%] w-0 h-0 ">
        <div id="google_translate_element"></div>
      </div>
      <div className="md:w-32 w-28">
        <NavLink
          to="/"
          preload="intent"
          title="Kijeka"
        >
          <img
            src={
              isScrolled
                ? "/static/images/KijekaLogo.webp"
                : "/static/images/KijekaLogoWhite.webp"
            }
            className="w-full h-full object-cover"
            alt="Logo"
            title="Kijeka"
            width="128"
            height="48"
            loading="eager"
            decoding="async"
            fetchpriority="high"
          />
        </NavLink>
      </div>

      {/* NavLinks */}
      <div>
        <ul
          className={
            isNavExpanded
              ? "fixed top-[54px] left-0 flex flex-col items-center justify-center h-screen w-full bg-white"
              : "lg:flex items-center hidden relative"
          }
        >
          {navlinks.map((link, index) => {
            if (link[0] === "Our Products") {
              return (
                <li
                  className={isNavExpanded ? "m-3 relative" : "mx-3 relative"}
                  key={index}
                  onMouseEnter={() => {
                    document
                      .getElementById("subCategoryDropdown")
                      .classList.remove("scale-y-0");
                    document
                      .getElementById("subCategoryDropdown")
                      .classList.remove("opacity-0");
                  }}
                  onMouseLeave={() => {
                    document
                      .getElementById("subCategoryDropdown")
                      .classList.add("scale-y-0");
                    document
                      .getElementById("subCategoryDropdown")
                      .classList.add("opacity-0");
                  }}
                >
                  <NavLink
                    to={link[1]}
                    preload="intent"
                    className={({ isActive }) =>
                      isNavExpanded
                        ? "flex flex-col text-kijeka-blue font-semibold " +
                          (isActive ? " navbar-active " : " navbar-inactive ")
                        : isScrolled
                          ? isActive
                            ? "navbar-active"
                            : "navbar-inactive"
                          : isActive
                            ? "navbar-active-white"
                            : "navbar-inactive-white"
                    }
                    onClick={() => {
                      setIsNavExpanded(false);
                      setActiveMenu("abc");
                    }}
                  >
                    {link[0]}
                  </NavLink>
                  <div
                    id="subCategoryDropdown"
                    className="absolute top-5 pt-5 -left-[80%] md:-left-[200%] scale-y-0 opacity-0 transition-all duration-300 origin-top shadow-xl rounded-lg overflow-hidden"
                  >
                    <div className="bg-white/70 backdrop-blur w-max p-10 md:grid md:grid-rows-6 md:grid-flow-col flex flex-col justify-center gap-x-10 py-5 ">
                      {category.map((item, index) => (
                        <div
                          key={index}
                          className="text-kijeka-blue font-medium text-sm my-2 scale-100 origin-left hover:scale-110 hover:font-semibold transition-all duration-300"
                        >
                          <a
                            target="_blank"
                            rel="noreferrer"
                            href={"https://www.kijeka.com/" + item[1]}
                          >
                            &#x2022; {item[0]}
                          </a>
                        </div>
                      ))}
                    </div>
                  </div>
                </li>
              );
            } else {
              return (
                <li className={isNavExpanded ? "p-5 " : "mx-3"} key={index}>
                  <NavLink
                    to={link[1]}
                    preload="intent"
                    className={({ isActive }) =>
                      isNavExpanded
                        ? "flex flex-col text-kijeka-blue font-semibold " +
                          (isActive ? " navbar-active " : " navbar-inactive ")
                        : isScrolled
                          ? isActive
                            ? "navbar-active"
                            : "navbar-inactive"
                          : isActive
                            ? "navbar-active-white"
                            : "navbar-inactive-white"
                    }
                    onClick={() => {
                      setIsNavExpanded(false);
                      setActiveMenu("abc");
                    }}
                  >
                    {link[0]}
                  </NavLink>
                </li>
              );
            }
          })}
        </ul>
      </div>

      <div
        className="flex items-center gap-8 relative max-sm:gap-2 "
        onMouseLeave={() => {
          document.getElementById("searchOverlay").classList.add("scale-y-0");
          document.getElementById("searchOverlay").classList.add("opacity-0");
          document.getElementById("dummyPathForSearch").style.height = 0;
          document.getElementById("dummyPathForSearch").style.width = 0;
        }}
      >
        {/* Hamburge Menu */}
        <button
          className="lg:hidden xl:hidden outline-none"
          onClick={() => {
            setIsNavExpanded(!isNavExpanded);
          }}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="h-5 w-5"
            viewBox="0 0 20 20"
            fill={isScrolled ? "#004B95" : "#ffffff"}
          >
            <path
              fillRule="evenodd"
              d="M3 5a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM9 15a1 1 0 011-1h6a1 1 0 110 2h-6a1 1 0 01-1-1z"
              clipRule="evenodd"
            />
          </svg>
        </button>
      </div>
    </div>
  );
};

export default Navbar;
